  "thread.flankAngleHint": "The angle between the two flanks of a tooth. 60° is the sharp V thread, 30° the trapezoid thread. At 90° or less no flank is flatter than 45°, so the thread prints without supports.",
  "prop.clearance": "Clearance (XY)",
  "prop.threadChamferTop": "Chamfer, top end",
  "prop.threadChamferBottom": "Chamfer, bottom end",
  "thread.axialClearanceHint": "Extra play along the thread, in mm, on top of the clearance: each tooth of the nut gets this much thinner while the diameter stays. For a loose-turning thread that does not rattle sideways: keep the clearance around 0.2 to 0.3 and set 0.2 here. At 0 the play comes from the clearance alone, which opens the flanks only about half as much.",
  "thread.clearanceHint": "The extra room across the whole diameter. A printed thread needs more than you would think: the gap between the flanks is only about half of it. Around 0.3 is tight, 0.4 usual, 0.5 loose. Print a test pair first.",
  "thread.boltClearanceHint": "Makes the bolt thinner by this much, for a metal nut that has no play of its own (0.3 to 0.4, as much as a printed nut would have). With a printed nut leave it at 0 and give the nut the room.",
