  "gridfinity.openingHint": "The depth is from the lip's top (the bin's top without the lip), the distance from the end the opening is placed at. Opened its whole width down to the floor, the side is open in full; a smaller opening keeps the side's corners and the lip beside it.",
  "prop.gridfinityOpeningCorner": "Opening corners",
  "prop.gridfinityOpeningCornerSize": "Opening corner size",
  "gridfinity.openingCornerHint": "The top and bottom corners of the openings, seen from outside the wall; under 0.5 mm they stay square. An opening across the whole side has no top corners.",
