  "sculpt.options.classicHint": "Smoothing and Attract as they were: the same strength smoothed less on a finely triangulated mesh, Bubble smooth gave back volume along the brush's facing, and Attract pulled onto the nearest surface of anything in reach. Off: smoothing is the same in millimetres on any scan, Bubble smooth keeps the volume, and Attract pulls only onto what the surface faces, stopping at the clearance.",
