  "screwBoss.custom": "Hole of my own",
  "screwBoss.insertOption": "{size} – hole {hole} mm, insert {length} mm",
  "screwBoss.insertShortOption": "{size} short – hole {hole} mm, insert {length} mm",
  "screwBoss.screwOption": "{size} – pilot hole {hole} mm",
  "screwBoss.insertHint": "The hole is a millimetre deeper than the insert. Printed holes come out a little smaller than drawn: print one boss to try, and adjust the hole by a tenth or two.",
  "screwBoss.screwHint": "Pilot hole about 0.8 times the screw, the post about 2.5 times it, the hole 2.5 screws deep. Printed holes come out a little smaller: try one first.",
  "screwBoss.customHint": "Type in the hole you need, say 3.4 mm for an M3 screw that goes through.",
  "screwBoss.through": "As deep as the post: the hole goes through.",
  "screwBoss.wall": "Wall round the hole: {wall} mm.",
  "screwBoss.wallThin": "Wall round the hole only {wall} mm – this fastener wants at least {min} mm. Make the post wider.",
  "screwBoss.gussetsHint": "Thin ribs from the post down to the floor brace it; 3 or 4 are usual.",
  "screwBoss.gussetsNoRoom": "No room for that many: make the gussets thinner or the footprint wider.",
  "prop.snapFitPart": "Part",
  "prop.snapFitWidth": "Width",
  "prop.snapFitHeight": "Height to the tip",
  "prop.snapFitDepth": "Depth with foot",
  "prop.snapFitThickness": "Arm thickness",
  "prop.snapFitUndercut": "Undercut",
  "prop.snapFitLeadAngle": "Entry angle",
  "prop.snapFitRetainAngle": "Holding angle",
  "prop.snapFitClearance": "Clearance",
  "prop.snapFitFoot": "Foot thickness",
  "snapFit.both": "Hook and catch",
  "snapFit.hook": "Hook only",
  "snapFit.catch": "Catch only",
  "snapFit.bothHint": "Both stand where they sit snapped in, the lid on top: put the hook's foot under the lid and the catch's back against the inside of the box wall, then Separate Parts splits them.",
  "snapFit.hookHint": "Just the hook, for a window in the wall or a catch of your own.",
  "snapFit.catchHint": "Just the ledge the hook snaps under; its back goes against the wall.",
  "snapFit.strainFine": "Bends {strain} % at its root as it snaps in: fine for PLA (up to about 2 %).",
  "snapFit.strainTough": "Bends {strain} % at its root: too much for PLA, fine for PETG or ABS (up to about 4 %). A longer or thinner arm bends less.",
  "snapFit.strainTooMuch": "Bends {strain} % at its root: it will break. Make the arm longer or thinner, or the undercut smaller.",
  "snapFit.leadHint": "From the direction it goes in: 30° slides in easily, smaller goes in more gently.",
  "snapFit.retainHint": "90° holds for good, 45° lets it be pulled apart again.",
  "snapFit.footHint": "The plate the arm hangs from, joined to the lid. 0: no foot.",
  "prop.ribStyle": "Kind",
  "prop.ribLength": "Length",
  "prop.ribGussetFoot": "Along the floor",
  "prop.ribGussetLeg": "Up the wall",
  "prop.ribThickness": "Thickness",
  "prop.ribTop": "Top",
  "rib.straight": "Straight rib",
  "rib.gusset": "Gusset",
  "rib.straightHint": "Stiffens a floor or a wall. Several in a row come from Pattern.",
  "rib.gussetHint": "A triangle that braces a wall against the floor: its upright side goes against the wall.",
  "rib.thicknessHint": "About as thick as the wall or a little thinner, a multiple of the line width: 0.8 or 1.6 mm with a 0.4 mm nozzle.",
  "rib.topFlat": "Flat",
  "rib.topRound": "Round",
  "rib.topChamfer": "Chamfered",
  "prop.ribFoot": "Foot",
  "prop.ribFootWidth": "Foot width",
  "prop.ribFootThickness": "Foot thickness",
  "rib.footHint": "A thin plate under the whole rib, the rib in its middle (a gusset's under its side along the floor). It holds the rib on the bed or the floor, so a thinner rib still stands.",
  "rib.footThicknessHint": "A few layers: 0.8 mm is four of 0.2 mm.",
  "prop.ribFootShape": "Foot shape",
  "rib.footSquare": "Square",
  "rib.footOval": "Oval",
  "rib.footShapeHint": "An oval foot has no corners that could lift off the bed as the plastic cools. It reaches just far enough past the rib's ends that they still stand on it: the shape gets longer, the rib keeps its length.",
  // Ported from layerling 1.165.
  "thread.headSquare": "Square head",
