  "thread.group.NPT": "NPT – US pipe, tapered",
  "thread.hint.NPT": "US tapered pipe thread (ASME B1.20.1), e.g. on fittings, valves, pressure gauges and air tools; it seals on the taper. The diameter is the pipe's, at the wide end.",
  "thread.group.bottle": "PCO – Bottles",
  "thread.hint.bottle": "PCO 1881: the 28 mm neck of most water and soda bottles. S60x6 (IBC): the outlet of IBC containers. Rod for the neck, Nut or Threaded hole for a cap.",
  "prop.threadStarts": "Starts",
  "prop.threadDivision": "Pitch (thread to thread)",
  "prop.threadTaper": "Tapered (1:16, NPT)",
  "thread.startsHint": "Threads side by side, as on a lead screw: a T8x8 has 4 starts at 2 mm pitch. 1 is an ordinary thread.",
  "thread.startsLeadHint": "Each thread climbs {lead} mm a turn ({starts} × {pitch} mm).",
  "prop.collarHeight": "Collar height",
  "prop.collarHeightHint": "A round collar between head and thread, such as a spacer under a star knob. 0 for none.",
  "prop.collarDiameter": "Collar diameter",
  "prop.driveSizeSlot": "Length of the slot; its width is a fifth of it.",
  "prop.driveSizeRobertson": "Across the flats of the square (#2, red, is 2.84 mm).",
  // Ported from layerling 1.165.
  "inspector.threadBoltAsHoleHint": "A threaded rod or screw has the bolt's full size and no play. As a hole it comes out too tight for the bolt: for a hole a bolt screws into, use Tapped hole.",
