  "lid.handle.tab": "Pull tab",
  "lid.handle.notch": "Finger notch",
  "lid.handleHint.tab": "A tab as thick as the plate, 6 mm out from its front edge (or the edge opposite the hinge), to pull the lid open by.",
  "lid.handleHint.notch": "A recess in the body's front wall (or the wall opposite the hinge) just below the lid's edge, for a finger to lift it; 0.8 mm of the wall always stays.",
  "lid.handleHint.tabSlide": "A tab as thick as the plate, 6 mm out from the lid's end at the wall it slides in through, to pull it out by.",
  "lid.handleHint.notchSlide": "Four grooves across the lid's top near its end at the wall it slides in through, for a thumb to push it out.",
  "lid.fingerNotchName": "{name} finger notch",
  "lid.error.handlePivot": "A pivot lid lies in the opening: it takes neither a pull tab nor a finger notch.",
  "lid.error.handleSideShort": "The side for the handle (the front, or the one opposite the hinge) is too short: a pull tab needs 16 mm, a finger notch 14 mm.",
  "lid.error.handleNotchNoRoom": "There is no room for a finger notch in the front wall: it needs a wall at least 1.2 mm thick and 5.8 mm of height below the lid's edge.",
  "lid.error.cutsKernel": "The dimples or the finger notch could not be cut into the body.",
  "lid.error.screwExtras": "A screw lid holds by its thread: magnets, a hinge, click bumps and a handle do not go with it.",
  "lid.error.screwNotRound": "A screw lid needs a round body: seen from above, its outside must be a circle (a cylinder, a tube, a round pot) from the rim down as far as the thread goes.",
  "lid.error.screwThinWall": "The body's wall is too thin for a screw lid's thread: it needs at least {wall} mm.",
  "lid.error.screwTooLow": "The body is too low for this thread, which reaches {height} mm down from the rim. Take fewer turns or a smaller pitch.",
  "lid.error.screwRimRound": "The rim is rounded or chamfered so far down that the straight wall below it is too short for this thread, which reaches {height} mm down from where the rounding begins. Take fewer turns or a smaller pitch, or round the rim less.",
  "lid.error.screwGapDeep": "The gap is too large for this thread: at most {gap} mm, half its depth, or the threads hardly hold. Take a smaller gap or a larger pitch.",
  "lid.error.screwKernel": "The thread could not be joined to the body.",
  "lid.error.screwStandardGapDeep": "The gap is too large for this thread: at most {gap} mm, half its depth, or the threads hardly hold.",
  "lid.error.screwStandardTooLow": "The body is too low for a {standard} neck, whose thread reaches {height} mm down from the rim.",
  "lid.error.screwStandardNeck": "The body's top is as wide as a {standard} neck, but it has to stay round and {neck} mm across for {depth} mm down from the rim, as far as the cap reaches.",
  "lid.error.neckFitShape": "Only a cylinder, a tube or a hollowed cylinder standing upright can be fitted to the neck: make this body's top the neck's size by hand.",
  "lid.error.screwInNotRound": "A screw-in lid needs a round body with a round opening: seen from above, its outside and its opening must be circles round the same middle (a cylinder, a tube, a round pot), from the rim down as far as the thread goes.",
  "lid.error.screwInShallow": "The opening is not deep enough for this plug, which reaches {height} mm down from the rim. Take fewer turns or a smaller pitch.",
  "lid.error.screwInSmallOpening": "The opening is too small for this thread: it must be at least {diameter} mm across. Take a smaller pitch or a smaller gap.",
  "lid.error.bayonetExtras": "A bayonet lid holds by its lugs: magnets, a hinge, click bumps and a handle do not go with it.",
  "lid.error.bayonetNotRound": "A bayonet lid needs a round body: seen from above, its outside must be a circle (a cylinder, a tube, a round pot) from the rim down as far as the cap reaches.",
  "lid.error.bayonetThinWall": "The body's wall is too thin for a bayonet lid's lugs: it needs at least {wall} mm.",
  "lid.error.bayonetTooLow": "The body is too low for this cap, which reaches {height} mm down from the rim. Take a smaller rim depth.",
  "lid.error.bayonetRimRound": "The rim is rounded or chamfered so far down that the straight wall below it is too short for this cap, which reaches {height} mm down from where the rounding begins. Take a smaller rim depth, or round the rim less.",
  "lid.error.bayonetGapDeep": "The gap is too large for these lugs: at most {gap} mm, half as far as they stand out, or the cap hardly holds. Take a smaller gap.",
  "lid.error.bayonetShallow": "The cap's rim is too short for these lugs: it must reach at least {depth} mm down, for the lugs and the ledge under them. Take a larger rim depth.",
  "lid.error.bayonetNoRoom": "These lugs do not fit round the body with room to turn. Take fewer lugs.",
  "lid.error.bayonetKernel": "The lugs could not be joined to the body.",
  "lid.error.slideExtras": "A slide-in lid holds in its grooves: magnets and a hinge do not go with it.",
  "lid.error.slideNotBox": "A slide-in lid needs a box: seen from above, the walls it slides along must run straight, and they must stand upright down past the grooves. For a round body take a screw lid or a bayonet lid.",
  "lid.error.slideThinWall": "The walls are too thin for the grooves: with this gap they must be at least {wall} mm thick. Take a smaller gap or thicker walls.",
  "lid.error.slideThinLid": "The lid is too thin for its grooves: with this gap make it at least {thickness} mm thick.",
  "lid.error.slideShallow": "The box is too shallow for this lid: its opening must reach at least {depth} mm down from the rim. Take a thinner lid.",
  "lid.error.slideThinFrame": "The frame is too low to keep the wall whole above the slot: set it to at least {frame} mm, or to 0.",
  "lid.error.slideFrameShallow": "The box is too shallow for this lid with its frame: its opening must reach at least {depth} mm down from the rim. Take a lower frame or a thinner lid.",
  "lid.error.slideKernel": "The grooves could not be cut into the body.",
  "lid.error.tetherType": "A tether goes only with a screw lid or a bayonet lid: it keeps a cap that is turned off the body.",
  "lid.error.tetherThinWall": "The body's wall below the cap is too thin for the bead that holds the tether's ring: it needs at least {wall} mm.",
  "lid.error.tetherNoNeck": "The tether's ring and the bead that holds it take {length} mm below the cap: the body must reach further down than that, round and as wide as at its top.",
  "lid.error.tetherCapShort": "The cap is too short for the tether's ring and the collar and bead it sits between: its rim must reach at least {depth} mm down. Take more turns or a larger rim depth.",
  "lid.error.flipTopType": "A flip-top goes only with a screw lid or a bayonet lid: a cap that stays on while its flap opens.",
