  "prop.gridfinityOverhangRight": "Overhang on the right",
  "gridfinity.overhangHint": "The bin above its feet reaches out by this much beyond the grid on that side, over a baseplate's padding to the drawer's wall, so nothing falls down beside it. The feet stay where they are and still stand in the baseplate. Typed as the plate's padding on that side, the bin ends flush with the plate.",
  "gridfinity.overhangOptionsHint": "Solid overhang keeps the inside, its compartments and dividers on the grid.",
  "gridfinity.overhangLipOnGridHint": "Keep the lip on the grid keeps the stacking lip there, so ordinary bins stack on this one, and makes the overhang solid with a flat top at the lip's foot, so Solid overhang is greyed out while it is on; without it the lip follows the wider outline, and a bin stacked on top is held only on the sides without overhang.",
  "prop.gridfinityOverhangChamfer": "Chamfer under the overhang",
  "gridfinity.overhangChamferHint": "0 leaves the overhang's underside flat on the padding, which needs supports to print. A height slopes it straight up from where it leaves the grid to that height at the outer wall, the same on every side, so a shorter side is steeper. A solid overhang can go higher than a hollow one.",
  "gridfinity.overhangSupportsHint": "Flatter than 45° {sides}: it may need supports to print properly.",
  "gridfinity.sideBack": "at the back",
  "gridfinity.sideFront": "at the front",
